const hits = ($('Get trending topics').first().json.hits || [])
  .filter(h => (h.points || 0) >= 50 && String(h.title || '').trim().split(/\s+/).length >= 4)
  .sort((a, b) => b.points - a.points);

if (!hits.length) {
  throw new Error('No suitable trending topics found');
}

const raw = $('List existing blogs').all().map(i => i.json);
const list = raw.length === 1 && Array.isArray(raw[0]) ? raw[0] : raw;
const existing = list.map(f => f.name || '').filter(Boolean).map(n => n.replace(/\.md$/, ''));

const STOP = new Set(['the', 'and', 'for', 'with', 'new', 'how', 'why', 'what', 'you', 'your', 'are', 'can', 'will', 'that', 'this', 'from', 'into', 'using', 'best', 'guide', 'tips']);

function keywords(slug) {
  return slug.split('-').filter(w => w.length > 3 && !STOP.has(w));
}

const existingWords = new Set(existing.flatMap(keywords));

const pick = hits.find(h => {
  const slug = h.title.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 60);
  const overlap = keywords(slug).filter(w => existingWords.has(w)).length;
  return overlap <= 1;
}) || hits[0];

const today = new Date().toISOString().slice(0, 10);

const systemPrompt = [
  'You write technical blog posts for the personal portfolio of a senior frontend engineer (React, TypeScript, CSS, performance, accessibility).',
  'Voice: first-person, direct, practical, mildly opinionated. Short paragraphs. No hype, no buzzword filler, no "in today\'s fast-paced world".',
  'Structure: a bold one-line thesis right after front-matter, then "##" sections. Include 1-3 focused code blocks (ts/tsx/css/bash) that are correct and runnable.',
  'Hard rules: never invent metrics, statistics, or personal anecdotes about employers. No named companies. 700-1100 words.',
  'The post MUST start with YAML front-matter, exactly this shape (double-quoted values):',
  '---',
  'title: "..."',
  'description: "One or two sentences, under 200 characters."',
  'datetime: "YYYY-MM-DD"',
  '---',
  'Output only the markdown. No preamble, no closing remarks.'
].join('\n');

const userPrompt = [
  `Write today's post (${today}).`,
  `Topic (from Hacker News discussion): "${pick.title}"`,
  pick.url ? `Reference for context: ${pick.url}` : '',
  existing.length ? `Existing posts on this blog (do not repeat their topics): ${existing.join(', ')}` : ''
].filter(Boolean).join('\n');

return [{ json: { topic: pick.title, url: pick.url || '', today, systemPrompt, userPrompt } }];

const draft = $('Draft blog').first().json.choices[0].message.content.trim();
let content = draft.replace(/^```(markdown|md)?\s*\n?/, '').replace(/\n?```\s*$/, '').trim();

if (!content.startsWith('---')) {
  throw new Error('Draft missing front-matter');
}

const fm = content.split('---')[1] || '';
const title = (fm.match(/title:\s*"([^"]+)"/) || [])[1];
const description = (fm.match(/description:\s*"([^"]+)"/) || [])[1];
let datetime = (fm.match(/datetime:\s*"?(\d{4}-\d{2}-\d{2})"?/) || [])[1];

if (!title || !description) {
  throw new Error('Front-matter missing title or description');
}

const today = $('Pick topic').first().json.today;
if (!datetime) datetime = today;

// normalize datetime to the quoted format the site expects
content = content.replace(/datetime:.*/, `datetime: "${datetime}"`);

const raw = $('List existing blogs').all().map(i => i.json);
const list = raw.length === 1 && Array.isArray(raw[0]) ? raw[0] : raw;
const existing = list.map(f => f.name || '').filter(Boolean).map(n => n.replace(/\.md$/, ''));
let slug = title.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 60).replace(/-+$/, '');
if (!slug) slug = `post-${today}`;
if (existing.includes(slug)) slug = `${slug}-${datetime}`;

const message = `blog: add "${title}" (auto-generated via n8n - review before sharing)`;

return [{ json: { slug, title, datetime, message, base64: Buffer.from(content, 'utf8').toString('base64') } }];
